/// <summary>
/// Calculates the line amount based on quantity, weight, and pricing rules.
/// </summary>
/// <param name="_qty">The quantity to calculate against.</param>
/// <returns>The calculated line amount.</returns>
public AmountCur calcLineAmount(Qty _qty)
{
    // Start with the base calculation from the parent method
    AmountCur amount = next calcLineAmount(_qty);

    // Retrieve item and sales line details
    ItemId itemId = this.parmItemId();
    SalesLine salesLine = this.parmSalesLine();

    UnitOfMeasureSymbol unitSales = salesLine.SalesUnit;

    // Cache flags to avoid repeated static method calls
    boolean isCWItem = PdsGlobal::pdsIsCWItem(itemId);
    boolean isPricedByWeight = METPricedByWeightCache::getPricedByWeightAttributeCached(itemId);


    // Only proceed if item is catch weight or priced by weight
    if ((isCWItem || isPricedByWeight) && salesLine.SalesType != SalesType::ReturnItem)
    {
        WMSOrderTrans wmsOrderTrans;
        METWHSPhysDimUOMSite metWHSPhysDimUOMSite;
        InventSiteId inventSiteId = salesLine.inventDim().InventSiteId;

        // Get warehouse transaction quantity (only if expedition is complete or activated)
        select firstonly Qty from wmsOrderTrans
            where wmsOrderTrans.InventTransId == salesLine.InventTransId
           && (wmsOrderTrans.expeditionStatus == WMSExpeditionStatus::Complete
               || wmsOrderTrans.expeditionStatus == WMSExpeditionStatus::Activated);

        // Get physical dimensions (weight per UOM for the site)
        select firstonly weight, NetWeight from metWHSPhysDimUOMSite
            where metWHSPhysDimUOMSite.ItemId == itemId
          && metWHSPhysDimUOMSite.UOM == unitSales
          && metWHSPhysDimUOMSite.SiteId == inventSiteId;

        AmountCur pickQty;

        // If warehouse transaction quantity exists
        if (wmsOrderTrans.Qty)
        {
            // If item is priced by weight but not catch weight, multiply by NetWeight
            pickQty = isPricedByWeight && !isCWItem
            ? wmsOrderTrans.Qty * metWHSPhysDimUOMSite.NetWeight
            : wmsOrderTrans.Qty;
        }
        else
        {
            // Otherwise, calculate based on sales quantity and NetWeight
            pickQty = metWHSPhysDimUOMSite.NetWeight * salesLine.SalesQty;
        }

        // Final amount = picked quantity × (price - discount)
        amount = round(pickQty * (salesLine.SalesPrice - salesLine.LineDisc), 0.01);
    }

    return amount;
}

/// <summary>
/// Calculates line amount forced.
/// </summary>
/// <param name = "_qty">Qty.</param>
/// <param name = "_checkPolicy">Check policy.</param>
/// <returns>Amount.</returns>
public AmountCur calcLineAmountForced(Qty _qty, PriceDiscPolicyCheckPolicy _checkPolicy)
{
    // Start with the base calculation from the parent method
    AmountCur amount = next calcLineAmountForced(_qty, _checkPolicy);

    // Retrieve item and sales line details
    ItemId itemId = this.parmItemId();
    SalesLine salesLine = this.parmSalesLine();
    InventDim inventDim = salesLine.inventDim();
    UnitOfMeasureSymbol unitSales = salesLine.SalesUnit;

    // Cache flags to avoid repeated static method calls
    boolean isCWItem = PdsGlobal::pdsIsCWItem(itemId);
    boolean isPricedByWeight = METPricedByWeightCache::getPricedByWeightAttributeCached(itemId);

    // Only proceed if item is catch weight or priced by weight
    if ((isCWItem || isPricedByWeight) && salesLine.SalesType != SalesType::ReturnItem)
    {
        WMSOrderTrans wmsOrderTrans;
        METWHSPhysDimUOMSite metWHSPhysDimUOMSite;

        // Get warehouse transaction quantity (only if expedition is complete or activated)
        select firstonly Qty from wmsOrderTrans
            where wmsOrderTrans.InventTransId == salesLine.InventTransId
           && (wmsOrderTrans.expeditionStatus == WMSExpeditionStatus::Complete
               || wmsOrderTrans.expeditionStatus == WMSExpeditionStatus::Activated);

        // Get physical dimensions (weight per UOM for the site)
        select firstonly weight, NetWeight from metWHSPhysDimUOMSite
            where metWHSPhysDimUOMSite.ItemId == itemId
          && metWHSPhysDimUOMSite.UOM == unitSales
          && metWHSPhysDimUOMSite.SiteId == inventDim.InventSiteId;

        AmountCur pickQty;

        // If warehouse transaction quantity exists
        if (wmsOrderTrans.Qty)
        {
            // If item is priced by weight but not catch weight, multiply by NetWeight
            pickQty = isPricedByWeight && !isCWItem
            ? wmsOrderTrans.Qty * metWHSPhysDimUOMSite.NetWeight
            : wmsOrderTrans.Qty;
        }
        else
        {
            // Otherwise, calculate based on sales quantity and NetWeight
            pickQty = metWHSPhysDimUOMSite.NetWeight * salesLine.SalesQty;
        }

        // Final amount = picked quantity × (price - discount)
        amount = round(pickQty * (salesLine.SalesPrice - salesLine.LineDisc), 0.01);
    }

    return amount;
}

/// <summary>
/// Retrieves the "Priced by weight" attribute value for a given item.
/// </summary>
/// <param name="_itemId">
/// The unique identifier of the item (Product Number) whose attribute value is being checked.
/// </param>
/// <returns>
/// A boolean value indicating whether the item is priced by weight:
/// - true  → Item is priced by weight
/// - false → Item is not priced by weight or attribute not found
/// </returns>
/// <remarks>
/// The method queries the EcoResProductAttributeValueEntity table to find the BooleanValue
/// associated with the "Priced by weight" attribute for the specified item.
/// If the attribute exists, its BooleanValue is returned; otherwise, false is returned.
/// </remarks>
public boolean getPricedByWeightAttributeValue(ItemId _itemId)
{
    METGetAttributeValue        getAttributeValue;
    boolean                     pricedByWeightAttributeValue;
    InventTable                 inventTable = InventTable::find(_itemId);
    METCachedAttributes         cachedAttributes = METCachedAttributes::find();

    if (inventTable.RecId
            && cachedAttributes.PricedByWeight)
    {
        getAttributeValue = METGetAttributeValue::newFromInventTable(inventTable);
        pricedByWeightAttributeValue = getAttributeValue.getAttributeValue(cachedAttributes.PricedByWeight);
    }

    return  pricedByWeightAttributeValue;
}
